import { cn } from '@/lib/cn'
import { formatItalianDate } from '@/lib/chiedi/dates'

/** The line every answer ends with: it was generated by an AI system, and the corpus date when known. */
export function AiNotice({ corpusAsOf, demo, className }: { corpusAsOf?: string; demo?: boolean; className?: string }) {
  const date = formatItalianDate(corpusAsOf)
  return (
    <p className={cn('text-caption text-ink-3', className)}>
      Risposta generata da un sistema di IA.
      {date && (
        <>
          {' '}
          Corpus al {date}
          {demo ? ' (dati di esempio)' : ''}.
        </>
      )}
    </p>
  )
}
